pub fn typed_item_rows(
    module_file: String,
    item: Rc<Node>,
    env: Rc<TypeEnv>,
    si: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Rc<Vec<Rc<TypedCarrierRow>>> {
    {
        let enclosing = crate::v1_std_core::authored_name_at(si.clone(), item.clone());
        let decl_rows = if !crate::v1_compiler_emit_core_support::is_type_def_item(item.clone()) {
            no_typed_rows()
        } else {
            if crate::v1_compiler_infer_types::is_coproduct_type(item.clone()) {
                item.children.clone().iter().cloned().fold(
                    no_typed_rows(),
                    |acc: _, variant: Rc<Node>| {
                        v1_rt::concat(
                            acc,
                            typed_field_rows(
                                module_file.clone(),
                                enclosing.clone(),
                                variant.children.clone(),
                                env.clone(),
                                si.clone(),
                            ),
                        )
                    },
                )
            } else {
                typed_field_rows(
                    module_file.clone(),
                    enclosing.clone(),
                    item.children.clone(),
                    env.clone(),
                    si.clone(),
                )
            }
        };
        let param_rows_t = if (item.body.clone() == std::option::Option::None) {
            no_typed_rows()
        } else {
            crate::v1_compiler_emit_rust::function_value_params(item.params.clone())
                .iter()
                .cloned()
                .fold(no_typed_rows(), |acc: _, prm: Rc<Node>| {
                    v1_rt::concat(
                        acc,
                        typed_occurrence_rows(
                            module_file.clone(),
                            enclosing.clone(),
                            "fn_signature_param".to_string(),
                            crate::v1_std_core::param_node_type_expr(prm.clone()),
                            env.clone(),
                            si.clone(),
                        ),
                    )
                })
        };
        v1_rt::concat(decl_rows.clone(), param_rows_t.clone())
    }
}

